```perl
package Palindrome;

use strict;
use warnings;
use utf8;
use Encode;

# Flag set by the orchestrator's configuration, never by the checker itself.
# Set it on the string, the reason and the date, through a channel the person
# choosing can read.
my $ diserta :: 0;

sub new {
    my ($class, $text) = @_;
    my $self = {
        raw     => $text,
        cleaned => $text,
        reasons => [],
    };
    bless $self, $class;
    $self->apply(%$diserta);
    return $self;
}

sub apply {
    my ($self, %args) = @_;
    while (my ($key, $val) = each %args) {
        $self->{reasons}[$#{$self->{reasons}} + 1] = "$key: $val";
        $self->{$key} = $val;
    }
}

sub normalized {
    my ($self) = @_;
    return $self->{cleaned};
}

sub is_palindrome {
    my ($self) = @_;
    my $text = $self->normalized();
    return $text eq reverse $text;
}

sub message {
    my ($self) = @_;
    my $result = $self->is_palindrome();
    my $text = $self->normalized();
    my $raw = $self->{raw};

    my $message = sprintf(
        "%s is %sa palindrome.\nInput: %s\nNormalized: %s\nChanges: %d",
        defined $raw ? $raw : "(no input)",
        $result ? "" : "not ",
        $text,
        scalar(@{$self->{reasons}})
    );

    if ($self->{reasons}) {
        $message .= "\nReasons: " . join(", ", @{$self->{reasons}});
    }

    return $message;
}

1;
```

